  const prevMs = cur.getTime() - 3600e3;

  const before = prevMs >= start.getTime() && prevMs < end.getTime();
  const seriesStart = new Date(start.getTime() - 3600e3);      // poprawka
  const after = prevMs >= seriesStart.getTime() && prevMs < end.getTime();

  const f = d => new Date(d).toLocaleString('pl-PL',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
  console.log(`${label}\n   teraz ${f(now)} | poprzednia godz. ${f(prevMs)}`);
  console.log(`   przed poprawką: ${before ? 'jest w oknie' : 'POZA OKNEM → brak danych'}`);
  console.log(`   po poprawce:    ${after ? 'jest w oknie' : 'POZA OKNEM'}\n`);
}
